#!/bin/bash
# 27_music_playlist_cover.sh
# 歌单页精修：封面接 Coil AsyncImage 加载真实海报图（灰色底占位保留）
set -e
cd "$(dirname "$0")/../.." 2>/dev/null || true
BASE="avbox"
PL_KT="$BASE/app/src/main/java/com/github/tvbox/osc/ui/music/playlist/PlaylistScreen.kt"

if [ -f "$PL_KT" ] && grep -q "真机海报图接入" "$PL_KT" 2>/dev/null; then
  echo "跳过（PlaylistScreen.kt 封面精修版已写入）"
  exit 0
fi

mkdir -p "$(dirname "$PL_KT")"
echo "" | base64 -d > "$PL_KT"
echo "已写入 playlist/PlaylistScreen.kt（Coil 封面版）"
